#include <bits/stdc++.h>
using namespace std;
#define MOD 1000000007
typedef unsigned long long ull;

struct Matrix {
    ull s[35][35];
    int size;
    friend Matrix operator*(const Matrix &a, const Matrix &b) {
        Matrix c;
        c.size = a.size;
        for (int i = 0; i < a.size; ++i) {
            for (int j = 0; j < a.size; ++j) {
                c.s[i][j] = 0;
                for (int k = 0; k < a.size; ++k) {
                    c.s[i][j] += a.s[i][k] * b.s[k][j];
                }
                c.s[i][j] %= MOD;
            }
        }
        return c;
    }
};

int main() {
    ull n, m;
    cin >> n >> m;
    Matrix base, identity;
    base.size = m + 1;
    for (int i = 0; i <= m; ++i) {
        base.s[i][i] = 1;
        base.s[0][i] = 1;
    }
    identity.size = m + 1;
    for (int i = 0; i <= m; ++i) {
        identity.s[i][i] = 1;
    }

    ull power = 0, factor = 1, tempY = 1, level = 0, step = 0;
    while (tempY * m <= n) {
        tempY *= m;
        ++level;
    }

    vector<vector<Matrix>> bi(level + 1, vector<Matrix>(m + 1));
    for (int t = 0; t <= level; ++t) {
        if (t > 0) {
            bi[t][0] = bi[t - 1][0];
            for (int i = 1; i < m; ++i) {
                bi[t][0] = bi[t][0] * bi[t - 1][i];
            }
        }
        for (int i = 1; i <= m; ++i) {
            bi[t][i] = bi[t][i - 1];
            for (int j = m - 2; j >= 0; --j) {
                for (int k = 0; k <= m; ++k) {
                    swap(bi[t][i].s[j][k], bi[t][i].s[j + 1][k]);
                }
            }
            for (int j = m - 2; j >= 0; --j) {
                for (int k = 0; k <= m; ++k) {
                    swap(bi[t][i].s[k][j], bi[t][i].s[k][j + 1]);
                }
            }
        }
    }

    Matrix result = identity;
    while (step < n) {
        if (step + tempY <= n) {
            step += tempY;
            result = result * bi[level][0];
            factor = (factor + 1) % m;
        } else {
            tempY /= m;
            --level;
        }
    }

    ull answer = 0;
    for (int i = 0; i <= m; ++i) {
        answer = (answer + result.s[i][m]) % MOD;
    }
    cout << answer << "\n";
}
